using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
class Inject {static void Main(string[] a){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[2]);resolver.AddSearchDirectory(System.IO.Path.GetDirectoryName(a[1]));var input=AssemblyDefinition.ReadAssembly(a[0],new ReaderParameters{AssemblyResolver=resolver});var helper=AssemblyDefinition.ReadAssembly(a[1]);var boot=input.MainModule.ImportReference(helper.MainModule.GetType("CW3Debug").Methods.Single(m=>m.Name=="Boot"));foreach(string t in new[]{"MainMenu","GameSpace","MessageDialogManager"}){var m=input.MainModule.GetType(t).Methods.Single(x=>x.Name=="Awake");var il=m.Body.GetILProcessor();il.InsertBefore(m.Body.Instructions[0],il.Create(OpCodes.Call,boot));Console.WriteLine(t+".Awake: one Boot call at entry");}input.Write(a[3]);}}
